/**
 * Read a class's captured `instanceCount` off the fixture, following the
 * root's link, so every count assertion tracks a recapture instead of
 * pinning a graph number.
 */
const readCapturedCount = (classUri: string): number => {
  const records = lobbyRecords as unknown as Record<
    string,
    Record<string, unknown> | undefined
  >;
  const link = records["client:root"]?.[`ontologyClass(uri:"${classUri}")`] as
    | { __ref?: string }
    | undefined;
  const count =
    link?.__ref === undefined
      ? undefined
      : (records[link.__ref] as { instanceCount?: unknown } | undefined)
          ?.instanceCount;
  if (typeof count !== "number") {
    throw new Error(`lobbyRecords lost its instanceCount for ${classUri}`);
  }
  return count;
};

/**
 * The captured fixture with one class's root link set to null, as the
 * store holds a class the graph lacks.
 */
const dropClass = (classUri: string): typeof lobbyRecords => {
  const records = structuredClone(lobbyRecords) as unknown as Record<
    string,
    Record<string, unknown>
  >;
  const root = records["client:root"];
  const key = `ontologyClass(uri:"${classUri}")`;
  if (root === undefined || !(key in root)) {
    throw new Error(`lobbyRecords lost its root link for ${classUri}`);
  }
  root[key] = null;
  return records as unknown as typeof lobbyRecords;
};

